export async function joinCode(code: string) { const c = code.trim().toLowerCase().replace(/\s+/g, '-'); if (!c) { toast('Type the room code first.', true); return } if (!chosen()) { toast('Choose a hero first.', true); return } await closeTable(); wake(); load(.08, 'Listening for the table'); app.joining = c; try { await bootP; await listen(c) } catch (e: any) { app.loading = null; app.joining = ''; toast(e?.message ?? 'Could not listen for the table.', true) } }
async function listen(c: string) { const t = await CodeTransport.open(c, false, relays()); if (app.joining !== c) { t.close(); return } const me = guest = new Guest(t, meInfo(), joinHooks()); setTimeout(() => { if (guest === me && !me.host && app.joining === c) load(.08, t.relays ? 'Knocking. Is the Dungeon Master’s page open and awake?' : 'Cannot reach the internet. Ask for a handshake scroll instead.') }, 12000) }
export async function joinLocal(id: string) { if (!chosen()) { toast('Choose a hero first.', true); return } await closeTable(); load(.1, 'Listening for the table'); app.joining = 'local'; await bootP; guest = new Guest(new LocalTransport(id, false), meInfo(), joinHooks()) }
let gscroll: ScrollTransport | null = null
export async function answerScroll(text: string): Promise<string | null> { if (!chosen()) { toast('Choose a hero first.', true); return null } await closeTable(); wake(); try { await bootP; gscroll?.close(); gscroll = new ScrollTransport(); const a = await gscroll.answer(text); guest = new Guest(gscroll, meInfo(), joinHooks()); return a } catch (e: any) { toast(e?.message ?? 'That invitation could not be read.', true); return null } }
export async function cancelJoin() { app.joining = ''; app.loading = null; await closeTable() }
