export const KEYS: [string, string, string?][] = [['1 – 5', 'First person, third person, isometric, top down, fly'], ['W A S D', 'Walk, or move the view'], ['Shift', 'Run'], ['E', 'Use what is in front of you'], ['Z', 'Sneak, or stop sneaking', 'player'], ['C', 'Character sheet', 'player'], ['I', 'Pack', 'player'], ['K', 'Spellbook', 'player'], ['J', 'Journal'], ['Enter', 'Speak or act in words'], ['Space', 'Throw the dice that are called for, or end your turn'], ['Esc', 'Stop aiming, close, leave a body'], ['Ctrl K', 'Find anything'], ['Alt click', 'Ping'], ['T', 'Torch'], ['G', 'Grid'], ['[ ]', 'Floor up, floor down'], ['Q E', 'Turn the isometric view'], ['B', 'Build', 'dm'], ['R', 'Turn the piece in hand', 'dm'], ['Del', 'Remove what is selected', 'dm'], ['P', 'Pause the game', 'dm'], ['Ctrl Z, Ctrl Y', 'Undo, redo', 'dm'], ['?', 'This list']]
function bindKeys(g: Game) {
  const modes: Mode[] = ['fps', 'tps', 'iso', 'top', 'fly']; window.addEventListener('keydown', (e: KeyboardEvent) => { if ((e.ctrlKey || e.metaKey) && e.code === 'KeyK' && app.screen === 'play') { e.preventDefault(); app.modal === 'palette' ? close() : open('palette') } if (e.code === 'Escape' && app.menu) app.menu = null; else if (e.code === 'Escape' && app.modal && document.activeElement && ['INPUT', 'TEXTAREA'].includes(document.activeElement.tagName)) close() })
  g.input.onKey = (k, e) => {
    if (app.screen !== 'play' || app.loading) return; if ((e.ctrlKey || e.metaKey) && k === 'KeyZ' && app.role === 'dm') { e.preventDefault(); e.shiftKey ? redoEdit() : undoEdit(); return } if ((e.ctrlKey || e.metaKey) && k === 'KeyY' && app.role === 'dm') { e.preventDefault(); redoEdit(); return } if ((e.ctrlKey || e.metaKey) && k === 'KeyS') { e.preventDefault(); saveNow().then(() => toast('Saved.')); return } if ((e.ctrlKey || e.metaKey) && k === 'KeyD' && app.editing) { e.preventDefault(); editor!.duplicate(); return } if (e.ctrlKey || e.metaKey) return
    const d = /^Digit([1-5])$/.exec(k); if (d && !e.altKey) { const m = modes[+d[1] - 1]; setMode(m); return }
    if (k === 'Escape') { if (app.menu) app.menu = null; else if (app.aim) aimAt(null); else if (app.modal) close(); else if (app.editing && (app.tool.tool !== 'select' || app.sel)) setTool({ tool: 'select' }); else if (app.editing) setEditing(false); else if (app.possess) possess(''); else if (app.selToken) selectToken(null); return } if (app.modal && app.modal !== 'palette') { if (k === 'KeyC' && app.modal === 'sheet') close(); return }
    if (k === 'KeyQ' && g.view.mode === 'iso') g.view.isoGoal += Math.PI / 2; if (k === 'KeyE' && g.view.mode === 'iso' && !app.near) g.view.isoGoal -= Math.PI / 2; if ((k === 'KeyE' || k === 'KeyF') && app.near && g.view.mode !== 'fly') interact(); if (k === 'KeyR' && app.editing) editor!.rotate(e.shiftKey ? -Math.PI / 12 : Math.PI / 4); if ((k === 'Delete' || k === 'Backspace') && app.editing) editor!.remove(); else if (k === 'Delete' && app.role === 'dm' && app.selToken && truth?.mons[app.selToken]) stage?.remove(app.selToken); if (k === 'KeyB' && app.role === 'dm') setEditing(!app.editing); if (k === 'KeyT') toggleTorch(); if (k === 'KeyG') setGrid(); if (k === 'Home' || k === 'KeyH' && g.view.flat) g.recenter(); if (k === 'PageUp' || k === 'BracketRight') stepLevel(1); if (k === 'PageDown' || k === 'BracketLeft') stepLevel(-1)
    if (app.seat && !app.editing) { if (k === 'KeyC') open('sheet'); if (k === 'KeyI') open('sheet', 'pack'); if (k === 'KeyK') open('sheet', 'spells'); if (k === 'KeyZ') void act({ k: 'act', a: 'sneak' }) } if (k === 'KeyJ') open('journal'); if (k === 'KeyP' && app.role === 'dm') setShared({ paused: !app.shared.paused }); if (e.key === '?') open('keys'); if (k === 'Enter') { e.preventDefault(); g.input.unlock(); app.feedOpen = true; setTimeout(() => document.querySelector<HTMLInputElement>('.feed textarea, .feed input')?.focus(), 30) } if (k === 'Space' && truth?.combat && g.view.mode !== 'fly') endTurn()
  }
}
export function setGrid() { if (app.role === 'dm') setShared({ grid: !app.shared.grid }); else if (editor) { editor.gridOn = !editor.gridOn } }
export function toggleTorch() { const g = game.value!; app.torch = !app.torch; g.torch = app.torch }
export function setMode(m: Mode) { const g = game.value!; if (app.role === 'dm' && !app.possess) { if (m === 'fps' || m === 'tps') m = 'fly'; if (m === 'fly') { const f = g.view.focus; void f } } else if (m === 'fly') return; g.setView(m); rings(); walkKey = '-'; marksNow() }
export function stepLevel(d: number) { const g = game.value!; if (!g.world || !g.view.flat) return; const r = g.world.range(); const l = Math.max(r.min, Math.min(r.max, g.shownLevel + d)); if (l !== g.shownLevel || d === 0) g.setViewLevel(l === g.level && !app.editing ? null : l); app.level = g.shownLevel; lastZ = ''; marksNow() }
export function interact() { const g = game.value!; if (app.near) { if (app.role === 'player' && !app.shared.doors && app.near.kind !== 'chest') { toast('The doors will not move for you.'); return } g.interact(app.near) } }
